svg.script:
var ns = "http://www.w3.org/2000/svg";
var dt = document.getElementById("dt");
var db = document.getElementById("db");
var phases = [].slice.call(document.querySelectorAll(".n"));
var phaseConnectors = [].slice.call(document.querySelectorAll(".phase-connector"));
var nextPhaseToUnlock = 0;

phases.forEach(function(phase, index) {
  if (index > 0) phase.classList.add("phase-hidden");
});
phaseConnectors.forEach(function(connector, index) {
  if (index > 0) connector.classList.add("phase-hidden");
});

function wrap(t, w) {
  while (t.firstChild) t.removeChild(t.firstChild);
  var words = t.getAttribute("data-x").split(" "), line = "";
  var tsp = document.createElementNS(ns, "tspan");
  tsp.setAttribute("x", t.getAttribute("x"));
  tsp.setAttribute("dy", "0");
  t.appendChild(tsp);

  words.forEach(function(wd) {
    if (wd === "•" && line) {
      tsp = document.createElementNS(ns, "tspan");
      tsp.setAttribute("x", t.getAttribute("x"));
      tsp.setAttribute("dy", "26");
      t.appendChild(tsp);
      line = wd;
      tsp.textContent = line;
      return;
    }
    var test = line ? line + " " + wd : wd;
    tsp.textContent = test;
    if (tsp.getComputedTextLength() > w && line) {
      tsp.textContent = line;
      tsp = document.createElementNS(ns, "tspan");
      tsp.setAttribute("x", t.getAttribute("x"));
      tsp.setAttribute("dy", "26");
      t.appendChild(tsp);
      line = wd;
      tsp.textContent = wd;
    } else {
      line = test;
    }
  });
}

function show(t, b) {
  dt.textContent = t;
  db.setAttribute("data-x", b);
  wrap(db, 1090);
}

var all = [].slice.call(document.querySelectorAll(".k"));
all.forEach(function(g) {
  function go() {
    var phaseIndex = phases.indexOf(g);
    if (phaseIndex === nextPhaseToUnlock && phaseIndex < phases.length - 1) {
      phases[phaseIndex + 1].classList.remove("phase-hidden");
      if (phaseConnectors[phaseIndex + 1]) {
        phaseConnectors[phaseIndex + 1].classList.remove("phase-hidden");
      }
      nextPhaseToUnlock++;
    }
    all.forEach(function(o) {
      o.classList.remove("sel");
      o.setAttribute("aria-pressed", "false");
    });
    g.classList.add("sel");
    g.setAttribute("aria-pressed", "true");
    show(g.getAttribute("data-t"), g.getAttribute("data-d"));
  }
  g.addEventListener("click", go);
  g.addEventListener("keydown", function(e) {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      go();
    }
  });
});

// Affichage initial
show(dt.getAttribute("data-t0"), db.getAttribute("data-x0"));
